import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, ActivityIndicator, Dimensions, Animated, Modal } from 'react-native';
import { Colors } from '../../constants/colors';
import { supabase } from '../../lib/supabase';
import { BarChart, LineChart } from 'react-native-gifted-charts';
import { Ionicons } from '@expo/vector-icons';
import { getStartOfWeek, formatDate } from '../../hooks/useBusinessLogic';
import { useFocusEffect, useRouter } from 'expo-router';
import { useTranslation } from '../../hooks/useTranslation';
import { useGlobal } from '../../context/GlobalContext';

class ChartErrorBoundary extends React.Component<any, { hasError: boolean }> {
  constructor(props: any) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError(error: any) {
    return { hasError: true };
  }
  componentDidCatch(error: any, errorInfo: any) {
    console.error("Chart rendering error:", error, errorInfo);
  }
  render() {
    if (this.state.hasError) {
      return <Text style={{ color: Colors.danger, padding: 20 }}>Unable to load chart</Text>;
    }
    return this.props.children;
  }
}

const screenWidth = Dimensions.get('window').width;

export default function ReportsScreen() {
  const router = useRouter();
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getStartOfWeek(new Date()));
  const [revenueData, setRevenueData] = useState<any[]>([]);
  const [trendData, setTrendData] = useState<any[]>([]);
  const [summary, setSummary] = useState({ totalRevenue: 0, totalProfit: 0, bestItem: '-', activeAlerts: 0 });
  const [expanded, setExpanded] = useState<string | null>(null);
  const { hasAnimatedRevenueChart, setHasAnimatedRevenueChart } = useGlobal();
  const animatedRevenue = useRef(new Animated.Value(0)).current;
  const animatedProfit = useRef(new Animated.Value(0)).current;
  const [displayRevenue, setDisplayRevenue] = useState(0);
  const [displayProfit, setDisplayProfit] = useState(0);
  const [workingDays, setWorkingDays] = useState<string[]>(['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']);
  const [selectedBar, setSelectedBar] = useState<number | null>(null);
  const [tooltipData, setTooltipData] = useState<any>(null);

  // isMounted prevents chart updates after navigation
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    return () => {
      setIsMounted(false);
    };
  }, []);

  const handleBarPress = useCallback((index: number, item: any) => {
    setSelectedBar(index);
    setTooltipData({
      day: item.label,
      date: item.fullDate,
      revenue: item.value,
      profit: item.profit,
      itemCount: item.itemCount,
    });
  }, []);

  const dismissTooltip = useCallback(() => {
    setSelectedBar(null);
    setTooltipData(null);
  }, []);

  const fetchReportData = async (weekStart: Date) => {
    setLoading(true);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) return;

      const { data: owner } = await supabase
        .from('owners')
        .select('*')
        .eq('user_id', session.user.id)
        .single();
      if (!owner) return;

      const ownerWorkingDays = owner.working_days || ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      setWorkingDays(ownerWorkingDays);

      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekEnd.getDate() + 6);

      const startStr = formatDate(weekStart);
      const endStr = formatDate(weekEnd);

      const { data: sales } = await supabase
        .from('daily_sales')
        .select('sale_date, total_revenue, total_profit, quantity_sold, items(item_name, cost_price)')
        .eq('owner_id', owner.id)
        .gte('sale_date', startStr)
        .lte('sale_date', endStr);

      const { data: alerts } = await supabase
        .from('alerts')
        .select('id')
        .eq('owner_id', owner.id)
        .gte('triggered_at', startStr)
        .lte('triggered_at', endStr);

      let totRev = 0, totProf = 0;
      const dailyRevMap: Record<string, number> = {};
      const dailyProfMap: Record<string, number> = {};
      const dailyAlertMap: Record<string, number> = {};
      const itemRevMap: Record<string, number> = {};
      const dailyQtyMap: Record<string, number> = {};

      for (let i = 0; i < 7; i++) {
        const d = new Date(weekStart);
        d.setDate(d.getDate() + i);
        const key = formatDate(d);
        dailyRevMap[key] = 0;
        dailyProfMap[key] = 0;
        dailyAlertMap[key] = 0;
        dailyQtyMap[key] = 0;
      }

      if (sales) {
        sales.forEach((s: any) => {
          const rev = Number(s.total_revenue) || 0;
          const qty = Number(s.quantity_sold) || 0;
          const item = Array.isArray(s.items) ? s.items[0] : s.items;

          let finalProf = 0;
          if (s.total_profit !== null && s.total_profit !== undefined && Number(s.total_profit) !== 0) {
            finalProf = Number(s.total_profit);
          } else if (item) {
            const costPrice = Number(item.cost_price || 0);
            finalProf = rev - (costPrice * qty);
          }

          totRev += rev;
          totProf += finalProf;
          const dateKey = s.sale_date;
          if (dateKey && dailyRevMap[dateKey] !== undefined) {
            dailyRevMap[dateKey] += rev;
            dailyProfMap[dateKey] += finalProf;
            dailyQtyMap[dateKey] += qty;
          }

          const itemName = s.items?.item_name || 'Unknown';
          itemRevMap[itemName] = (itemRevMap[itemName] || 0) + rev;
        });
      }

      if (alerts) {
        alerts.forEach((a: any) => {
          const dateKey = a.triggered_at?.split('T')[0];
          if (dateKey && dailyAlertMap[dateKey] !== undefined) {
            dailyAlertMap[dateKey]++;
          }
        });
      }

      let bestItem = '-';
      let maxRev = -1;
      for (const [item, rev] of Object.entries(itemRevMap)) {
        if (rev > maxRev) {
          maxRev = rev;
          bestItem = item;
        }
      }

      // Build chart data ΓÇö onPress moved out of fetchReportData
      const revData = Object.keys(dailyRevMap).sort().map((d) => {
        const dayName = new Date(d).toLocaleDateString('en-US', { weekday: 'short' });
        const isWorkingDay = ownerWorkingDays.includes(dayName);
        return {
          value: isWorkingDay ? dailyRevMap[d] : 0,
          profit: isWorkingDay ? dailyProfMap[d] : 0,
          alerts: isWorkingDay ? dailyAlertMap[d] : 0,
          itemCount: isWorkingDay ? dailyQtyMap[d] : 0,
          label: dayName,
          fullDate: new Date(d).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' }),
          frontColor: isWorkingDay ? Colors.accent : Colors.border,
          labelTextStyle: { color: isWorkingDay ? Colors.textSecondary : Colors.border },
        };
      });

      setRevenueData(revData);
      setTrendData(revData);
      setSummary({
        totalRevenue: totRev,
        totalProfit: totProf,
        bestItem,
        activeAlerts: alerts ? alerts.length : 0,
      });
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useFocusEffect(
    useCallback(() => {
      let isActive = true;

      const loadData = async () => {
        if (isActive) {
          await fetchReportData(currentWeekStart);
          dismissTooltip();
        }
      };

      loadData();

      return () => {
        isActive = false;
        animatedRevenue.stopAnimation();
        animatedProfit.stopAnimation();
      };
    }, [currentWeekStart])
  );

  // Fixed useEffect ΓÇö listeners added and removed cleanly
  useEffect(() => {
    if (loading) return;

    let isActive = true;

    const idRev = animatedRevenue.addListener(({ value }) => {
      if (isActive) {
        setDisplayRevenue(Math.round(value));
      }
    });

    const idProf = animatedProfit.addListener(({ value }) => {
      if (isActive) {
        setDisplayProfit(Math.round(value));
      }
    });

    if (!hasAnimatedRevenueChart) {
      animatedRevenue.setValue(0);
      animatedProfit.setValue(0);
      setDisplayRevenue(0);
      setDisplayProfit(0);

      Animated.parallel([
        Animated.timing(animatedRevenue, {
          toValue: summary.totalRevenue,
          duration: 1500,
          useNativeDriver: false,
        }),
        Animated.timing(animatedProfit, {
          toValue: summary.totalProfit,
          duration: 1500,
          useNativeDriver: false,
        }),
      ]).start(() => {
        if (isActive) {
          setHasAnimatedRevenueChart(true);
        }
      });
    } else {
      setDisplayRevenue(summary.totalRevenue);
      setDisplayProfit(summary.totalProfit);
    }

    return () => {
      isActive = false;
      animatedRevenue.removeListener(idRev);
      animatedProfit.removeListener(idProf);
    };
  }, [summary.totalRevenue, summary.totalProfit, loading, hasAnimatedRevenueChart, animatedRevenue, animatedProfit]);

  const changeWeek = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + (direction === 'prev' ? -7 : 7));
    if (newDate > new Date()) return;
    setCurrentWeekStart(newDate);
  };

  const isCurrentWeek = formatDate(currentWeekStart) === formatDate(getStartOfWeek(new Date()));
  const weekEnd = new Date(currentWeekStart);
  weekEnd.setDate(weekEnd.getDate() + 6);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>{t('Reports')}</Text>
      </View>

      <View style={styles.weekSelector}>
        <TouchableOpacity onPress={() => changeWeek('prev')} style={styles.navBtn}>
          <Ionicons name="chevron-back" size={24} color={Colors.primary} />
        </TouchableOpacity>
        <Text style={styles.weekText}>
          {currentWeekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} -{' '}
          {weekEnd.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
        </Text>
        <TouchableOpacity onPress={() => changeWeek('next')} style={styles.navBtn} disabled={isCurrentWeek}>
          <Ionicons name="chevron-forward" size={24} color={isCurrentWeek ? Colors.border : Colors.primary} />
        </TouchableOpacity>
      </View>

      {loading ? (
        <ActivityIndicator size="large" color={Colors.primary} style={styles.loader} />
      ) : (
        <ScrollView style={styles.content} contentContainerStyle={styles.scrollContent}>

          {/* Weekly Summary */}
          <View style={styles.summaryGrid}>
            <TouchableOpacity
              style={[styles.summaryCard, expanded === 'revenue' && styles.expandedCard]}
              onPress={() => setExpanded(expanded === 'revenue' ? null : 'revenue')}
            >
              <Text style={styles.summaryLabel}>{t('Total Revenue')}</Text>
              <Text style={styles.summaryValue}>Γé╣{displayRevenue.toLocaleString('en-IN')}</Text>
              <Ionicons
                name={expanded === 'revenue' ? 'chevron-up' : 'chevron-down'}
                size={16}
                color={Colors.textSecondary}
                style={styles.chevron}
              />
            </TouchableOpacity>

            <TouchableOpacity
              style={[styles.summaryCard, expanded === 'profit' && styles.expandedCard]}
              onPress={() => setExpanded(expanded === 'profit' ? null : 'profit')}
            >
              <Text style={styles.summaryLabel}>{t('Total Profit')}</Text>
              <Text style={styles.summaryValue}>Γé╣{displayProfit.toLocaleString('en-IN')}</Text>
              <Ionicons
                name={expanded === 'profit' ? 'chevron-up' : 'chevron-down'}
                size={16}
                color={Colors.textSecondary}
                style={styles.chevron}
              />
            </TouchableOpacity>

            <TouchableOpacity style={styles.summaryCard} disabled>
              <Text style={styles.summaryLabel}>{t('Top Item')}</Text>
              <Text style={styles.summaryValueText} numberOfLines={1}>{summary.bestItem}</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.summaryCard}
              onPress={() => router.push('/dashboard/alerts' as any)}
            >
              <Text style={styles.summaryLabel}>{t('Weekly Alerts')}</Text>
              <Text style={styles.summaryValue}>{summary.activeAlerts}</Text>
              <Ionicons name="chevron-forward" size={16} color={Colors.textSecondary} style={styles.chevron} />
            </TouchableOpacity>
          </View>

          {/* Drill-down Daily List */}
          {expanded && (
            <View style={styles.drillDownContainer}>
              <Text style={styles.drillDownTitle}>
                {expanded === 'revenue' ? t('Daily Revenue') : t('Daily Profit')}
              </Text>
              {revenueData.map((day, idx) => (
                <View key={idx} style={styles.drillDownRow}>
                  <Text style={styles.drillDownDay}>{day.label}</Text>
                  <Text style={styles.drillDownValue}>
                    {expanded === 'revenue'
                      ? `Γé╣${day.value.toLocaleString('en-IN')}`
                      : `Γé╣${day.profit.toLocaleString('en-IN')}`}
                  </Text>
                </View>
              ))}
            </View>
          )}

          {/* Daily Revenue Bar Chart */}
          <View style={styles.chartCard} onTouchStart={() => dismissTooltip()}>
            <Text style={styles.chartTitle}>{t('Daily Revenue')}</Text>

            {/* isMounted check prevents chart crash on navigation */}
            {isMounted && revenueData.length > 0 && (
              <View style={{ position: 'relative' }}>
                <ChartErrorBoundary>
                  <BarChart
                    data={revenueData.map((item, index) => ({
                      ...item,
                      onPress: () => handleBarPress(index, item),
                    }))}
                    barWidth={28}
                    spacing={25}
                    initialSpacing={20}
                    yAxisLabelWidth={50}
                    noOfSections={5}
                    maxValue={Math.max(...revenueData.map(d => d.value), 1000) * 1.2}
                    barBorderRadius={6}
                    frontColor={Colors.accent}
                    yAxisThickness={0}
                    xAxisThickness={0}
                    hideRules
                    yAxisTextStyle={{ color: Colors.textSecondary, fontSize: 10 }}
                    xAxisLabelTextStyle={{ color: Colors.textSecondary, fontSize: 10 }}
                  />
                </ChartErrorBoundary>
              </View>
            )}
          </View>

          {/* Sales Trend Line Chart */}
          <View style={styles.chartCard}>
            <Text style={styles.chartTitle}>{t('Sales Trend')}</Text>

            {/* isMounted check prevents chart crash on navigation */}
            {isMounted && trendData.length > 0 && (
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                <ChartErrorBoundary>
                  <LineChart
                    data={trendData}
                    color={Colors.primary}
                    thickness={3}
                    dataPointsColor={Colors.primary}
                    noOfSections={5}
                    maxValue={Math.max(...trendData.map(d => d.value), 1000) * 1.2}
                    hideRules
                    yAxisThickness={0}
                    xAxisThickness={0}
                    yAxisTextStyle={{ color: Colors.textSecondary, fontSize: 10 }}
                    xAxisLabelTextStyle={{ color: Colors.textSecondary, fontSize: 10 }}
                    curved
                    spacing={45}
                    initialSpacing={20}
                    yAxisLabelWidth={50}
                  />
                </ChartErrorBoundary>
              </ScrollView>
            )}
          </View>

        </ScrollView>
      )}

      {tooltipData && (
        <Modal
          transparent
          visible={true}
          animationType="fade"
          onRequestClose={dismissTooltip}
        >
          <TouchableOpacity
            style={{
              flex: 1,
              backgroundColor: 'rgba(0,0,0,0.3)',
              justifyContent: 'center',
              alignItems: 'center',
            }}
            onPress={dismissTooltip}
            activeOpacity={1}
          >
            <View style={{
              backgroundColor: '#FFFFFF',
              borderRadius: 14,
              padding: 18,
              minWidth: 220,
              borderWidth: 1.5,
              borderColor: '#1E3A5F',
              elevation: 20,
              shadowColor: '#000',
              shadowOffset: { width: 0, height: 6 },
              shadowOpacity: 0.2,
              shadowRadius: 10,
            }}>
              <Text style={{
                fontSize: 15,
                fontWeight: 'bold',
                color: '#1E3A5F',
                marginBottom: 10,
              }}>
                {tooltipData.day}, {tooltipData.date}
              </Text>
              <View style={{
                height: 1,
                backgroundColor: '#E5E7EB',
                marginBottom: 10,
              }}/>
              <Text style={{
                fontSize: 13,
                color: '#1A1A1A',
                marginBottom: 6,
              }}>
                Revenue: Γé╣{Number(tooltipData.revenue).toLocaleString('en-IN')}
              </Text>
              <Text style={{
                fontSize: 13,
                color: '#1A1A1A',
                marginBottom: 6,
              }}>
                Profit: Γé╣{Number(tooltipData.profit).toLocaleString('en-IN')}
              </Text>
              <Text style={{
                fontSize: 13,
                color: '#1A1A1A',
              }}>
                Items Sold: {tooltipData.itemCount}
              </Text>
              <Text style={{
                fontSize: 11,
                color: '#6B7280',
                marginTop: 12,
                textAlign: 'center',
              }}>
                Tap anywhere to close
              </Text>
            </View>
          </TouchableOpacity>
        </Modal>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: Colors.navyLight, paddingTop: 50 },
  header: { padding: 20, paddingBottom: 10 },
  title: { fontSize: 28, fontWeight: 'bold', color: Colors.primary },
  weekSelector: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 20, marginBottom: 20 },
  navBtn: { padding: 8, backgroundColor: Colors.card, borderRadius: 8, borderWidth: 1, borderColor: Colors.border },
  weekText: { fontSize: 16, fontWeight: 'bold', color: Colors.textPrimary },
  loader: { flex: 1, justifyContent: 'center' },
  content: { flex: 1, paddingHorizontal: 20 },
  scrollContent: { paddingBottom: 40 },
  summaryGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: 12, marginBottom: 24 },
  summaryCard: { flex: 1, minWidth: '45%', backgroundColor: Colors.card, padding: 15, borderRadius: 12, borderWidth: 1, borderColor: Colors.border, position: 'relative' },
  expandedCard: { borderColor: Colors.primary, backgroundColor: Colors.navyLight },
  chevron: { position: 'absolute', top: 12, right: 12 },
  summaryLabel: { fontSize: 12, color: Colors.textSecondary, marginBottom: 8 },
  summaryValue: { fontSize: 18, fontWeight: 'bold', color: Colors.primary },
  summaryValueText: { fontSize: 16, fontWeight: 'bold', color: Colors.primary },
  drillDownContainer: { backgroundColor: Colors.card, padding: 20, borderRadius: 16, marginBottom: 24, borderWidth: 1, borderColor: Colors.border },
  drillDownTitle: { fontSize: 16, fontWeight: 'bold', color: Colors.primary, marginBottom: 15 },
  drillDownRow: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: Colors.border },
  drillDownDay: { fontSize: 14, color: Colors.textPrimary, fontWeight: '500' },
  drillDownValue: { fontSize: 14, color: Colors.primary, fontWeight: 'bold' },
  chartCard: { backgroundColor: Colors.card, padding: 20, borderRadius: 16, marginBottom: 20, borderWidth: 1, borderColor: Colors.border, elevation: 2, shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 3, position: 'relative', zIndex: 10 },
  chartTitle: { fontSize: 16, fontWeight: 'bold', color: Colors.primary, marginBottom: 20 },
});
